  END IF;
  IF NEW.status = 'APRESIASI' AND OLD.status NOT IN ('MEMBEDAH', 'APRESIASI') THEN
    RAISE EXCEPTION 'clinic_sessions: APRESIASI hanya dari MEMBEDAH, bukan %', OLD.status;
  END IF;
  RETURN NEW;
END;
$$;


