--
-- Name: petition_votes_count_sync(); Type: FUNCTION; Schema: madevi; Owner: madevi
--

CREATE FUNCTION madevi.petition_votes_count_sync() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (TG_OP = 'INSERT') THEN
    UPDATE "madevi".catalog_petitions
       SET vote_count = vote_count + 1 WHERE id = NEW.petition_id;
    RETURN NEW;
  ELSIF (TG_OP = 'DELETE') THEN
    UPDATE "madevi".catalog_petitions
       SET vote_count = vote_count - 1 WHERE id = OLD.petition_id;
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$$;


