--
-- Name: refresh_karya_badges(); Type: FUNCTION; Schema: madevi; Owner: madevi
--

CREATE FUNCTION madevi.refresh_karya_badges() RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Hapus badge yang tidak lagi valid, lalu isi yang valid.
  DELETE FROM "madevi".karya_badges
   WHERE principal_id NOT IN (
     SELECT p.principal_id FROM "madevi".social_posts p
      WHERE p.post_type = 'KARYA'
        AND p.deleted_at IS NULL
        AND EXISTS (SELECT 1 FROM "madevi".social_posts c
                     WHERE c.parent_karya_id = p.id)
   );

  SELECT DISTINCT p.principal_id, 'INDUK_IDE'
    FROM "madevi".social_posts p
   WHERE p.post_type = 'KARYA'
     AND p.deleted_at IS NULL
     AND (SELECT COUNT(*) FROM "madevi".social_posts c
           WHERE c.parent_karya_id = p.id) >= 5
  ON CONFLICT (principal_id, badge) DO NOTHING;

  SELECT DISTINCT p.principal_id, 'KAKEK_IDE'
    FROM "madevi".social_posts p
   WHERE p.post_type = 'KARYA'
     AND p.deleted_at IS NULL
     AND (SELECT COUNT(*) FROM "madevi".karya_lineage l
           WHERE l.ancestor_id = p.id) >= 25
  ON CONFLICT (principal_id, badge) DO NOTHING;
END;
$$;


ALTER FUNCTION madevi.refresh_karya_badges() OWNER TO madevi;

