    CONSTRAINT backup_logs_status_check CHECK ((status = ANY (ARRAY['IN_PROGRESS'::text, 'SUCCESS'::text, 'FAILED'::text]))),
    CONSTRAINT backup_logs_verification_result_check CHECK (((verification_result IS NULL) OR (verification_result = ANY (ARRAY['OK'::text, 'MISMATCH'::text, 'MISSING'::text, 'ERROR'::text]))))
);


ALTER TABLE madevi.backup_logs OWNER TO madevi;

--
-- Name: COLUMN backup_logs.manifest; Type: COMMENT; Schema: madevi; Owner: madevi
--

COMMENT ON COLUMN madevi.backup_logs.manifest IS 'P16: manifest backup — daftar file, ukuran, checksum per file, jumlah baris tabel kunci.';


--
-- Name: COLUMN backup_logs.schema_version; Type: COMMENT; Schema: madevi; Owner: madevi
--

COMMENT ON COLUMN madevi.backup_logs.schema_version IS 'P16: nomor migrasi tertinggi saat backup dibuat; restore menolak mismatch.';


--
-- Name: COLUMN backup_logs.verified_at; Type: COMMENT; Schema: madevi; Owner: madevi
--

COMMENT ON COLUMN madevi.backup_logs.verified_at IS 'P16: kapan backup terakhir diverifikasi (restore uji atau checksum ulang). NULL = belum terbukti.';


--
-- Name: COLUMN backup_logs.retention_until; Type: COMMENT; Schema: madevi; Owner: madevi
--

