--
-- Name: content_packets; Type: TABLE; Schema: madevi; Owner: madevi
--

CREATE TABLE madevi.content_packets (
    id uuid NOT NULL,
    article_id uuid NOT NULL,
    family_id uuid NOT NULL,
    edition_number integer DEFAULT 1 NOT NULL,
    language text DEFAULT 'id'::text NOT NULL,
    space_key text NOT NULL,
    format_profile text NOT NULL,
    packet_status text DEFAULT 'PROPOSED'::text NOT NULL,
    source_dossier_status text DEFAULT 'MISSING'::text NOT NULL,
    claim_map_status text DEFAULT 'MISSING'::text NOT NULL,
    rights_status text DEFAULT 'MISSING'::text NOT NULL,
    freshness_policy text DEFAULT 'STABLE'::text NOT NULL,
    as_of_date date,
    next_review_at date,
    scope_boundary text DEFAULT ''::text NOT NULL,
    open_risks text DEFAULT ''::text NOT NULL,
    handoff_note text DEFAULT ''::text NOT NULL,
    created_by uuid NOT NULL,
    updated_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT content_packets_check CHECK ((((space_key = 'explore'::text) AND (format_profile = 'ATLAS'::text)) OR ((space_key = 'tutorial'::text) AND (format_profile = 'PRACTICE'::text)))),
    CONSTRAINT content_packets_check1 CHECK (((freshness_policy <> 'VOLATILE'::text) OR (as_of_date IS NOT NULL))),
    CONSTRAINT content_packets_check2 CHECK (((freshness_policy <> 'CHECK_PERIODIC'::text) OR (next_review_at IS NOT NULL))),
    CONSTRAINT content_packets_check3 CHECK (((packet_status <> 'APPROVED'::text) OR ((source_dossier_status = 'VERIFIED'::text) AND (claim_map_status = 'READY'::text) AND (rights_status = ANY (ARRAY['CLEARED'::text, 'RESTRICTED'::text]))))),
    CONSTRAINT content_packets_claim_map_status_check CHECK ((claim_map_status = ANY (ARRAY['MISSING'::text, 'PARTIAL'::text, 'READY'::text]))),
    CONSTRAINT content_packets_edition_number_check CHECK ((edition_number > 0)),
    CONSTRAINT content_packets_format_profile_check CHECK ((format_profile = ANY (ARRAY['ATLAS'::text, 'PRACTICE'::text]))),
    CONSTRAINT content_packets_freshness_policy_check CHECK ((freshness_policy = ANY (ARRAY['STABLE'::text, 'CHECK_PERIODIC'::text, 'VOLATILE'::text]))),
    CONSTRAINT content_packets_handoff_note_check CHECK ((length(handoff_note) <= 5000)),
    CONSTRAINT content_packets_language_check CHECK ((language = ANY (ARRAY['id'::text, 'en'::text]))),
    CONSTRAINT content_packets_open_risks_check CHECK ((length(open_risks) <= 3000)),
    CONSTRAINT content_packets_packet_status_check CHECK ((packet_status = ANY (ARRAY['PROPOSED'::text, 'DOSSIER_READY'::text, 'DRAFT'::text, 'REVIEW'::text, 'APPROVED'::text, 'ARCHIVED'::text]))),
    CONSTRAINT content_packets_rights_status_check CHECK ((rights_status = ANY (ARRAY['MISSING'::text, 'IDENTIFIED'::text, 'CLEARED'::text, 'RESTRICTED'::text]))),
    CONSTRAINT content_packets_scope_boundary_check CHECK ((length(scope_boundary) <= 3000)),
    CONSTRAINT content_packets_source_dossier_status_check CHECK ((source_dossier_status = ANY (ARRAY['MISSING'::text, 'PARTIAL'::text, 'READY'::text, 'VERIFIED'::text]))),
    CONSTRAINT content_packets_space_key_check CHECK ((space_key = ANY (ARRAY['explore'::text, 'tutorial'::text])))
);


ALTER TABLE madevi.content_packets OWNER TO madevi;

