    CONSTRAINT content_relations_position_check CHECK (("position" >= 0)),
    CONSTRAINT content_relations_rationale_check CHECK (((length(TRIM(BOTH FROM rationale)) >= 3) AND (length(TRIM(BOTH FROM rationale)) <= 1000))),
    CONSTRAINT content_relations_relation_type_check CHECK ((relation_type = ANY (ARRAY['RELATED'::text, 'PREREQUISITE'::text, 'SEQUEL'::text, 'CONCEPT'::text, 'APPLICATION'::text, 'SAFETY_REFERENCE'::text, 'SUPERSEDES'::text, 'CONTRADICTS'::text]))),
