--
-- Name: jasa_order_queue; Type: VIEW; Schema: madevi; Owner: madevi
--

CREATE VIEW madevi.jasa_order_queue AS
 SELECT o.id,
    'UNDANGAN'::text AS kind,
    o.status,
    o.revision_count,
    o.revision_limit,
    o.schema_version,
    o.price_agreed,
    o.created_at,
    o.updated_at,
    o.completed_at,
        CASE
            WHEN ((o.status = 'IN_REVISION'::text) AND (o.updated_at < (CURRENT_TIMESTAMP - '3 days'::interval))) THEN 'HIGH'::text
            WHEN ((o.status = 'PENDING_APPROVAL'::text) AND (o.created_at < (CURRENT_TIMESTAMP - '1 day'::interval))) THEN 'MEDIUM'::text
            ELSE 'NORMAL'::text
        END AS urgency,
        CASE
            WHEN (o.status = ANY (ARRAY['PENDING_APPROVAL'::text, 'APPROVED'::text])) THEN 'ADMIN'::text
            WHEN (o.status = 'IN_REVISION'::text) THEN 'USER'::text
            ELSE 'NONE'::text
        END AS waiting_on,
    o.public_slug
   FROM madevi.invitation_orders o
UNION ALL
 SELECT o.id,
    'LOGO'::text AS kind,
    o.status,
    o.revision_count,
    o.revision_limit,
    o.schema_version,
    o.price_agreed,
    o.created_at,
    o.updated_at,
    o.completed_at,
        CASE
            WHEN ((o.status = 'IN_REVISION'::text) AND (o.updated_at < (CURRENT_TIMESTAMP - '3 days'::interval))) THEN 'HIGH'::text
            WHEN ((o.status = 'PENDING_APPROVAL'::text) AND (o.created_at < (CURRENT_TIMESTAMP - '1 day'::interval))) THEN 'MEDIUM'::text
            ELSE 'NORMAL'::text
        END AS urgency,
        CASE
            WHEN (o.status = ANY (ARRAY['PENDING_APPROVAL'::text, 'APPROVED'::text])) THEN 'ADMIN'::text
            WHEN (o.status = 'IN_REVISION'::text) THEN 'USER'::text
            ELSE 'NONE'::text
        END AS waiting_on,
    NULL::text AS public_slug
   FROM madevi.logo_orders o
UNION ALL
 SELECT s.id,
    s.kind,
    s.status,
    s.revision_count,
    s.revision_limit,
    s.brief_version AS schema_version,
    ((s.price_snapshot ->> 'snapshotPrice'::text))::numeric(15,2) AS price_agreed,
    s.created_at,
    s.updated_at,
    s.completed_at,
        CASE
            WHEN ((s.status = 'IN_REVISION'::text) AND (s.updated_at < (CURRENT_TIMESTAMP - '3 days'::interval))) THEN 'HIGH'::text
            WHEN ((s.status = 'PENDING_APPROVAL'::text) AND (s.created_at < (CURRENT_TIMESTAMP - '1 day'::interval))) THEN 'MEDIUM'::text
            ELSE 'NORMAL'::text
        END AS urgency,
        CASE
            WHEN (s.status = ANY (ARRAY['PENDING_APPROVAL'::text, 'APPROVED'::text])) THEN 'ADMIN'::text
            WHEN (s.status = 'IN_REVISION'::text) THEN 'USER'::text
            ELSE 'NONE'::text
        END AS waiting_on,
    NULL::text AS public_slug
   FROM madevi.service_orders s;


ALTER VIEW madevi.jasa_order_queue OWNER TO madevi;

--
-- Name: VIEW jasa_order_queue; Type: COMMENT; Schema: madevi; Owner: madevi
--

COMMENT ON VIEW madevi.jasa_order_queue IS 'P11: antrean Admin terpadu dengan filter urgensi (HIGH/MEDIUM/NORMAL) dan waiting_on (ADMIN/USER/NONE).';


