--
-- Name: principals; Type: TABLE; Schema: madevi; Owner: madevi
--

CREATE TABLE madevi.principals (
    id uuid NOT NULL,
    business_code text NOT NULL,
    kind text NOT NULL,
    role text NOT NULL,
    approval_status text NOT NULL,
    entitlement_status text NOT NULL,
    social_status text NOT NULL,
    display_name text NOT NULL,
    email text,
    is_test boolean DEFAULT false NOT NULL,
    lifecycle_status text DEFAULT 'ACTIVE'::text NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by uuid,
    updated_by uuid,
    deleted_at timestamp with time zone,
    version bigint DEFAULT 1 NOT NULL,
    username text,
    phone text,
    full_name text,
    gender text,
    birth_date date,
    city text,
    education_status text,
    profile_description text DEFAULT ''::text NOT NULL,
    avatar_object_id uuid,
    contact_verified_at timestamp with time zone,
    approval_decided_at timestamp with time zone,
    trial_started_at timestamp with time zone,
    trial_expires_at timestamp with time zone,
    terms_version_seen text,
    deletion_scheduled_at timestamp with time zone,
    ui_theme text,
    ui_language text,
    ui_preferences_updated_at timestamp with time zone,
    role_kind text,
    tools_trial_total integer DEFAULT 5 NOT NULL,
    tools_trial_remaining integer,
    tools_trial_setup_at timestamp with time zone,
    ui_preferences jsonb,
    CONSTRAINT principals_approval_status_check CHECK ((approval_status = ANY (ARRAY['PENDING'::text, 'APPROVED'::text, 'REJECTED'::text]))),
    CONSTRAINT principals_business_code_check CHECK ((business_code ~ '^[A-Z0-9_-]{3,64}$'::text)),
    CONSTRAINT principals_check CHECK (((lifecycle_status = 'DELETED'::text) = (deleted_at IS NOT NULL))),
    CONSTRAINT principals_display_name_check CHECK (((length(display_name) >= 1) AND (length(display_name) <= 120))),
    CONSTRAINT principals_entitlement_status_check CHECK ((entitlement_status = ANY (ARRAY['NONE'::text, 'TRIAL'::text, 'PAID'::text, 'EDUCATION'::text]))),
    CONSTRAINT principals_gender_check CHECK ((gender = ANY (ARRAY['PEREMPUAN'::text, 'LAKI_LAKI'::text, 'LAINNYA'::text]))),
    CONSTRAINT principals_kind_check CHECK ((kind = ANY (ARRAY['OWNER'::text, 'MEMBER'::text, 'SERVICE'::text]))),
    CONSTRAINT principals_lifecycle_status_check CHECK ((lifecycle_status = ANY (ARRAY['ACTIVE'::text, 'SUSPENDED'::text, 'DELETED'::text]))),
    CONSTRAINT principals_role_check CHECK ((role = ANY (ARRAY['OWNER'::text, 'MEMBER'::text, 'SERVICE'::text]))),
    CONSTRAINT principals_role_kind_check CHECK ((role_kind = ANY (ARRAY['ADMIN'::text, 'USER'::text]))),
    CONSTRAINT principals_social_status_check CHECK ((social_status = ANY (ARRAY['ENABLED'::text, 'RESTRICTED'::text, 'DISABLED'::text]))),
    CONSTRAINT principals_tools_trial_remaining_check CHECK (((tools_trial_remaining IS NULL) OR (tools_trial_remaining >= 0))),
    CONSTRAINT principals_tools_trial_total_check CHECK ((tools_trial_total >= 0)),
    CONSTRAINT principals_trial_window_check CHECK ((((trial_started_at IS NULL) AND (trial_expires_at IS NULL)) OR ((trial_started_at IS NOT NULL) AND (trial_expires_at = (trial_started_at + '30 days'::interval))))),
    CONSTRAINT principals_ui_language_check CHECK ((ui_language = ANY (ARRAY['id'::text, 'en'::text]))),
    CONSTRAINT principals_ui_theme_check CHECK ((ui_theme = ANY (ARRAY['light'::text, 'dark'::text, 'madevi-on'::text]))),
    CONSTRAINT principals_version_check CHECK ((version > 0))
);


ALTER TABLE madevi.principals OWNER TO madevi;

--
-- Name: principals_role_view; Type: VIEW; Schema: madevi; Owner: madevi
--

CREATE VIEW madevi.principals_role_view AS
 SELECT id,
    COALESCE(role_kind,
        CASE role
            WHEN 'OWNER'::text THEN 'ADMIN'::text
            ELSE 'USER'::text
        END) AS role_kind,
    role AS role_legacy,
    kind,
    approval_status,
    entitlement_status,
    lifecycle_status
   FROM madevi.principals
  WHERE (deleted_at IS NULL);


ALTER VIEW madevi.principals_role_view OWNER TO madevi;

