    release_date date,
    changelog text DEFAULT ''::text NOT NULL,
    requirements_system text DEFAULT ''::text NOT NULL,
    is_test boolean DEFAULT false NOT NULL,
    lifecycle_status text DEFAULT 'ACTIVE'::text NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT software_versions_changelog_check CHECK ((length(changelog) <= 5000)),
    CONSTRAINT software_versions_lifecycle_status_check CHECK ((lifecycle_status = ANY (ARRAY['ACTIVE'::text, 'DISABLED'::text, 'ARCHIVED'::text]))),
    CONSTRAINT software_versions_requirements_system_check CHECK ((length(requirements_system) <= 2000)),
    CONSTRAINT software_versions_version_check CHECK ((version ~ '^\d+\.\d+\.\d+([-.]\w+)?$'::text))
);


ALTER TABLE madevi.software_versions OWNER TO madevi;

--
-- Name: storage_objects; Type: TABLE; Schema: madevi; Owner: madevi
--

CREATE TABLE madevi.storage_objects (
    id uuid NOT NULL,
    owner_principal_id uuid NOT NULL,
    reservation_id uuid NOT NULL,
    storage_state text DEFAULT 'QUARANTINE'::text NOT NULL,
    assessment_status text DEFAULT 'UNASSESSED'::text NOT NULL,
    relative_path text NOT NULL,
    media_type text NOT NULL,
    size_bytes bigint NOT NULL,
    sha256 character(64) NOT NULL,
    original_name text NOT NULL,
    is_test boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    deleted_at timestamp with time zone,
    version bigint DEFAULT 1 NOT NULL,
    CONSTRAINT storage_objects_assessment_status_check CHECK ((assessment_status = ANY (ARRAY['UNASSESSED'::text, 'SAFE'::text, 'UNSAFE'::text]))),
    CONSTRAINT storage_objects_check CHECK (((storage_state = 'DELETED'::text) = (deleted_at IS NOT NULL))),
    CONSTRAINT storage_objects_original_name_check CHECK ((((length(original_name) >= 1) AND (length(original_name) <= 255)) AND (POSITION(('/'::text) IN (original_name)) = 0) AND (POSITION((chr(92)) IN (original_name)) = 0))),
    CONSTRAINT storage_objects_relative_path_check CHECK ((relative_path ~ '^(quarantine|objects)/[0-9a-f-]{36}[.]bin$'::text)),
    CONSTRAINT storage_objects_size_bytes_check CHECK ((size_bytes > 0)),
    CONSTRAINT storage_objects_storage_state_check CHECK ((storage_state = ANY (ARRAY['QUARANTINE'::text, 'ACTIVE'::text, 'REJECTED'::text, 'DELETED'::text]))),
    CONSTRAINT storage_objects_version_check CHECK ((version > 0))
);


ALTER TABLE madevi.storage_objects OWNER TO madevi;

