    status text DEFAULT 'AJUAN'::text NOT NULL,
    week_number integer NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT story_chapters_body_len CHECK (((char_length(body) >= 20) AND (char_length(body) <= 2400))),
    CONSTRAINT story_chapters_status_check CHECK ((status = ANY (ARRAY['AJUAN'::text, 'KANON'::text, 'ARSIP'::text]))),
    CONSTRAINT story_chapters_word_count CHECK ((array_length(string_to_array(TRIM(BOTH FROM body), ' '::text), 1) <= 300))
);


