--
-- Name: taxonomy_nodes; Type: TABLE; Schema: madevi; Owner: madevi
--

CREATE TABLE madevi.taxonomy_nodes (
    revision_id uuid NOT NULL,
    node_id uuid NOT NULL,
    parent_id uuid,
    level text NOT NULL,
    local_code text NOT NULL,
    path_code text NOT NULL,
    name text NOT NULL,
    slug text NOT NULL,
    path_slug text NOT NULL,
    sort_order integer NOT NULL,
    visibility text DEFAULT 'PUBLIC'::text NOT NULL,
    lifecycle_status text DEFAULT 'ACTIVE'::text NOT NULL,
    empty_marker text,
    source_file text NOT NULL,
    source_line integer NOT NULL,
    source_virtual_path text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT taxonomy_nodes_empty_marker_check CHECK ((empty_marker = ANY (ARRAY['KOSONG'::text, 'RENCANA_ARTIKEL'::text]))),
    CONSTRAINT taxonomy_nodes_level_check CHECK ((level = ANY (ARRAY['R'::text, 'D'::text, 'K'::text, 'M'::text, 'SM'::text, 'T'::text, 'ST'::text, 'J'::text]))),
    CONSTRAINT taxonomy_nodes_lifecycle_status_check CHECK ((lifecycle_status = ANY (ARRAY['ACTIVE'::text, 'ARCHIVED'::text]))),
    CONSTRAINT taxonomy_nodes_local_code_check CHECK ((local_code ~ '^(R|D|K|M|SM|T|ST|J)[1-9][0-9]*$'::text)),
    CONSTRAINT taxonomy_nodes_name_check CHECK (((length(name) >= 1) AND (length(name) <= 500))),
    CONSTRAINT taxonomy_nodes_path_code_check CHECK ((path_code ~ '^R[1-5](\.(D|K|M|SM|T|ST|J)[1-9][0-9]*)*$'::text)),
    CONSTRAINT taxonomy_nodes_path_slug_check CHECK ((path_slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*(\/[a-z0-9]+(?:-[a-z0-9]+)*)*$'::text)),
    CONSTRAINT taxonomy_nodes_slug_check CHECK ((slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'::text)),
    CONSTRAINT taxonomy_nodes_sort_order_check CHECK ((sort_order >= 0)),
    CONSTRAINT taxonomy_nodes_source_line_check CHECK ((source_line > 0)),
    CONSTRAINT taxonomy_nodes_version_check CHECK ((version > 0)),
    CONSTRAINT taxonomy_nodes_visibility_check CHECK ((visibility = ANY (ARRAY['PUBLIC'::text, 'OWNER_ONLY'::text])))
);


ALTER TABLE madevi.taxonomy_nodes OWNER TO madevi;

