    promoted_at timestamp with time zone,
    CONSTRAINT taxonomy_revisions_batch_cursor_check CHECK ((batch_cursor >= 0)),
    CONSTRAINT taxonomy_revisions_check CHECK (((status = ANY (ARRAY['ACTIVE'::text, 'RETIRED'::text])) = (promoted_at IS NOT NULL))),
    CONSTRAINT taxonomy_revisions_expected_node_count_check CHECK ((expected_node_count >= 0)),
    CONSTRAINT taxonomy_revisions_loaded_node_count_check CHECK ((loaded_node_count >= 0)),
    CONSTRAINT taxonomy_revisions_status_check CHECK ((status = ANY (ARRAY['STAGING'::text, 'ACTIVE'::text, 'RETIRED'::text, 'ABORTED'::text])))
);


ALTER TABLE madevi.taxonomy_revisions OWNER TO madevi;

